properties.query:
// KQL needs constant regexes, so each pattern is listed once for the filter and once for labelling.
let aws_key = @"\b(AKIA|ASIA)[0-9A-Z]{16}\b";
let secret_near_key = @"(?i:secret)[^\n]{0,20}[A-Za-z0-9/+]{40}";
let private_key = @"-----BEGIN [A-Z ]*PRIVATE KEY-----";
let github_token = @"\bgh[pousr]_[A-Za-z0-9]{36}\b";
let slack_token = @"\bxox[baprs]-[A-Za-z0-9-]{10,}";
let iban_hu = @"\bHU\d{2}(?: ?\d{4}){6}\b";
LLMAppLogs_CL
| where event_type in ("completion", "tool_call")
| extend Output = iff(event_type == "completion", completion, tool_args)
| where isnotempty(Output)
| extend SecretTypes = set_difference(pack_array(
      iff(Output matches regex aws_key, "aws_access_key_id", ""),
      iff(Output matches regex secret_near_key, "secret_near_key", ""),
      iff(Output matches regex private_key, "private_key_pem", ""),
      iff(Output matches regex github_token, "github_token", ""),
      iff(Output matches regex slack_token, "slack_token", ""),
      iff(Output matches regex iban_hu, "iban_hu", "")), dynamic([""]))
| where array_length(SecretTypes) > 0
| project TimeGenerated, user_id, src_ip, session_id, request_id, event_type, tool_name, tool_target,
          SecretTypes, Output

// queryPeriod (20m) covers the retrieval side; only egress newer than one run interval
// triggers, so overlapping runs do not alert twice on the same call.
let trigger_window = 10m;
let window = 10m;
let corporate_domain = "acme-freight.hu";
let http_allowlist = dynamic(["learn.microsoft.com", "github.com"]);
let external_content = LLMAppLogs_CL
    | where event_type == "retrieval" and doc_source != "internal-wiki"
    | project RetrievedAt = TimeGenerated, session_id, doc_id, doc_source, doc_title;
LLMAppLogs_CL
| where event_type == "tool_call" and tool_name in ("send_email", "http_get")
| where TimeGenerated > ago(trigger_window)
| extend Target = tolower(tool_target)
| where not(Target == corporate_domain or Target endswith strcat(".", corporate_domain))
| where not(tool_name == "http_get" and Target in (http_allowlist))
| project TimeGenerated, session_id, user_id, src_ip, tool_name, Target
| join kind=inner external_content on session_id
| where TimeGenerated between (RetrievedAt .. (RetrievedAt + window))
| summarize TimeGenerated = min(TimeGenerated), SourceDocs = make_set(doc_id), DocSources = make_set(doc_source),
            Tools = make_set(tool_name), Targets = make_set(Target)
    by session_id, user_id, src_ip

let threshold = 10;
// queryPeriod is twice the frequency so windows spanning a run boundary are seen whole;
// only windows with activity in the latest interval alert, to avoid duplicates.
let trigger_window = 5m;
LLMAppLogs_CL
| where event_type == "tool_call"
| sort by session_id asc, TimeGenerated asc
| extend Window = row_window_session(TimeGenerated, 5m, 5m, session_id != prev(session_id))
| summarize TimeGenerated = min(TimeGenerated), LastCall = max(TimeGenerated), ToolCalls = count(),
            Denied = countif(tool_status == "denied"), Tools = make_set(tool_name), Targets = make_set(tool_target, 25)
    by session_id, user_id, src_ip, Window
| where ToolCalls >= threshold and LastCall > ago(trigger_window)
| project-away Window

let agent_config = @"(?i)(\.vscode/(settings|mcp)\.json|\.cursor/|\.claude/(settings[^/]*\.json|agents/|commands/)|(^|/)mcp\.json|\.continue/config|copilot-instructions\.md|(^|/)(AGENTS|CLAUDE|GEMINI)\.md|\.windsurf/|\.kiro/)";
let shell_write_to_config = @"(?i)(>>?|\btee\b|\bsed\s+-i\b|\bcp\b|\bmv\b)[^|;]{0,80}(\.vscode/|\.cursor/|\.claude/|mcp\.json|AGENTS\.md|CLAUDE\.md|copilot-instructions\.md)";
let approval_off = @"(?i)autoApprove|dangerously|\byolo\b|bypassPermissions|--no-confirm";
LLMAppLogs_CL
| where event_type == "tool_call"
| where (tool_name == "write_file" and tool_target matches regex agent_config)
    or (tool_name == "run_shell" and tool_args matches regex shell_write_to_config)
| extend DisablesApproval = tool_args matches regex approval_off
| project TimeGenerated, user_id, src_ip, session_id, request_id, tool_name, tool_target, tool_approval,
          DisablesApproval, tool_args

let injection = @"(?i)\b(ignore|disregard|forget|override)\b[^.\n]{0,30}\b(previous|prior|above|earlier|preceding|system)\b[^.\n]{0,20}\b(instructions?|prompts?|rules|directions|guidelines)\b|\bnew instructions?\s*:";
let addressed_to_agent = @"(?i)\b(note|message|instructions?) (to|for) the (ai|assistant|ai assistant|llm|model|agent)\b|\bassistant instructions\s*:|\b(ai|llm) (assistant|agent)\s*:|\bno need to (ask|tell|inform) the user\b|\bdo not (tell|mention|inform)\b[^.\n]{0,20}\buser\b";
let remediation = @"(?i)\bto fix (this|the) (error|issue|problem)\b[^.\n]{0,40}\brun\b|`[^`]*\b(curl|wget|npx|npm (i|install)|pip install|bash|sh -c)\b[^`]*`";
LLMAppLogs_CL
| where event_type == "tool_call" and isnotempty(tool_result)
| where tool_result matches regex injection or tool_result matches regex addressed_to_agent
    or tool_result matches regex remediation
| project TimeGenerated, user_id, src_ip, session_id, request_id, tool_name, mcp_server, tool_target,
          tool_result
